        for name in ['Ian Jones', 'Hannah Miller', 'George Miller', 'Julia Garcia', 'Julia Davis', 'George Jones', 'Charlie Smith', 'Ian Garcia', 'Fiona Martinez', 'Ian Brown', 'Julia Smith']:
            if name in content:
                print(f'Mentions: {name}')
EOF

